// SPDX-License-Identifier: MPL-2.0
// Oracle for mathjax-go's internal mhchem engine (pattern matcher, JavaScript
// regexp translation, texifier and ToTeX), which D2 reaches through \ce and \pu in
// LaTeX labels. Run by tools/fixtures/mathtext-txt.toml:
//
//	mathtext-mhchem-oracle pattern|regexp|texify|expand INPUT.json > OUTPUT.json
//
// INPUT.json holds rows generated by scripts/fixture-gen-mhchem.py; the
// program adds the oracle fields and writes the rows back (indented, keys
// sorted). The ABI mirrors below follow internal/mhchem at the module version
// pinned in go.mod; recheck them whenever that version moves.
package main

import (
	"encoding/json"
	"fmt"
	"os"
	"reflect"
	_ "unsafe"

	_ "github.com/d2lang/mathjax-go" // links internal/mhchem
)

type matchToken struct {
	S       string
	A       []string
	IsArray bool
}

type patternHit struct {
	Token     matchToken
	Remainder string
}

type jsGroup struct {
	text   string
	Length int
}

type jsMatch struct {
	Index  int
	Length int
	text   string
	groups []jsGroup
}

//go:linkname mhchemLoadData github.com/d2lang/mathjax-go/internal/mhchem.LoadData
func mhchemLoadData() (*byte, error)

//go:linkname mhchemMatchPattern github.com/d2lang/mathjax-go/internal/mhchem.matchPattern
func mhchemMatchPattern(*byte, string, string) (*patternHit, error)

//go:linkname mhchemCompile github.com/d2lang/mathjax-go/internal/mhchem.compileJSRegexp
func mhchemCompile(string) (*byte, error)

//go:linkname mhchemFind github.com/d2lang/mathjax-go/internal/mhchem.(*jsRegexp).FindStringMatch
func mhchemFind(*byte, string) (*jsMatch, error)

//go:linkname mhchemTexify github.com/d2lang/mathjax-go/internal/mhchem.texify
func mhchemTexify([]any, bool) (string, error)

// ToTeX(input string, mode Mode) with Mode a string type.
//
//go:linkname mhchemToTeX github.com/d2lang/mathjax-go/internal/mhchem.ToTeX
func mhchemToTeX(string, string) (string, error)

// parserError reports a mhchem *Error as {id, message}; any other error is fatal.
func parserError(err error) any {
	if err == nil {
		return nil
	}
	v := reflect.ValueOf(err)
	if v.Kind() != reflect.Pointer || !v.Elem().FieldByName("ID").IsValid() {
		fail(fmt.Errorf("unexpected error type %T: %w", err, err))
	}
	return map[string]any{"id": v.Elem().FieldByName("ID").String(), "message": err.Error()}
}

func fail(err error) {
	fmt.Fprintln(os.Stderr, err)
	os.Exit(1)
}

func main() {
	if len(os.Args) != 3 {
		fail(fmt.Errorf("usage: %s pattern|regexp|texify|expand INPUT.json", os.Args[0]))
	}
	data, err := os.ReadFile(os.Args[2])
	if err != nil {
		fail(err)
	}
	var rows []map[string]any
	if err := json.Unmarshal(data, &rows); err != nil {
		fail(err)
	}
	switch os.Args[1] {
	case "pattern":
		tables, err := mhchemLoadData()
		if err != nil {
			fail(err)
		}
		for _, r := range rows {
			hit, err := mhchemMatchPattern(tables, r["name"].(string), r["input"].(string))
			r["hit"], r["error"] = nil, parserError(err)
			if hit != nil {
				var token any = hit.Token.S
				if hit.Token.IsArray {
					token = hit.Token.A
				}
				r["hit"] = map[string]any{"token": token, "remainder": hit.Remainder}
			}
		}
	case "regexp":
		for _, r := range rows {
			re, err := mhchemCompile(r["source"].(string))
			if err != nil {
				fail(err)
			}
			m, err := mhchemFind(re, r["input"].(string))
			if err != nil {
				fail(err)
			}
			r["match"] = nil
			if m != nil {
				groups := []string{}
				for _, g := range m.groups {
					groups = append(groups, g.text)
				}
				r["match"] = map[string]any{"index": m.Index, "length": m.Length, "text": m.text, "groups": groups}
			}
		}
	case "texify":
		for _, r := range rows {
			tex, err := mhchemTexify(r["values"].([]any), r["outer"].(bool))
			r["tex"], r["error"] = tex, parserError(err)
		}
	case "expand":
		for _, r := range rows {
			tex, err := mhchemToTeX(r["input"].(string), r["mode"].(string))
			r["tex"], r["error"] = tex, parserError(err)
		}
	default:
		fail(fmt.Errorf("unknown mode %q", os.Args[1]))
	}
	out, err := json.MarshalIndent(rows, "", "  ")
	if err != nil {
		fail(err)
	}
	if _, err := os.Stdout.Write(append(out, '\n')); err != nil {
		fail(err)
	}
}
